  display:flex;
  justify-content:center;
  pointer-events:none;
  margin:var(--space-3) 0
}
.day-divider span{
  font-size:var(--text-xs);
  color:var(--fg-3);
  padding:.35rem .7rem;
  border-radius:999px;
  border:1px solid var(--sep)
}
.msg{
  display:grid;
  gap:.55rem;
