  text-transform:uppercase;
  font-weight:700
}
.msg-head .time{
  margin-left:auto;
  font-size:var(--text-xs);
  color:var(--fg-3)
}
.msg.user{justify-items:end}
.msg.user .msg-head,
.msg.user .bubble-wrap{width:min(100%,720px);margin-left:auto}
.msg.ai .msg-head,
.msg.ai .bubble-wrap{width:min(100%,860px);margin-right:auto}
.bubble-wrap{
  position:relative
}
.bubble{
  position:relative;
  padding:1rem 1rem;
  border-radius:1.5rem;
  border:1px solid var(--sep);
