    0 14px 40px rgba(41,80,180,.22)
}
.u.bubble::after{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(220px 80px at 20% 0,rgba(255,255,255,.24),transparent 50%),
    linear-gradient(180deg,rgba(255,255,255,.06),transparent 60%);
  pointer-events:none
}
.ai-bubble{
  background:transparent;
  border-color:transparent;
  box-shadow:none;
  padding:.1rem 0 0
}
.ai-bubble .md > *:first-child{margin-top:0}
.ai-bubble .md > *:last-child{margin-bottom:0}
.msg-actions{
  display:flex;
  justify-content:flex-end;
  gap:.4rem;
  margin-top:.55rem;
  opacity:.72
}
.msg.ai .msg-actions{justify-content:flex-start}
.msg-actions button{
  min-width:34px;
  min-height:34px;
  border-radius:.8rem;
  border:1px solid var(--sep);
  background:transparent;
  padding:0 .65rem;
  display:inline-flex;
  align-items:center;
  justify-content:center
}
.msg-actions button svg{width:16px;height:16px}
.md{
  color:inherit;
  font-size:var(--text-base);
  word-wrap:break-word;
  overflow-wrap:anywhere
}
.md h1,.md h2,.md h3,.md h4,.md h5,.md h6{
  line-height:1.15;
  margin:1.15em 0 .55em;
  font-weight:800
}
.md h1{font-size:1.8rem}
.md h2{font-size:1.48rem}
.md h3{font-size:1.25rem}
.md h4{font-size:1.1rem}
.md p{margin:.78em 0;color:inherit}
.md strong{font-weight:800}
.md em{font-style:italic}
.md hr{
  border:0;
  height:1px;
  background:var(--sep);
  margin:1rem 0
}
.md ul,.md ol{
  margin:.7rem 0 .9rem 1.2rem;
  padding:0
}
.md li{margin:.35rem 0}
.md blockquote{
  margin:1rem 0;
  padding:.2rem 0 .2rem .9rem;
  border-left:3px solid color-mix(in srgb,var(--accent) 42%,var(--sep));
  color:var(--fg-2)
}
.md code{
  font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace;
  font-size:.92em;
  padding:.16rem .38rem;
  border-radius:.45rem;
  background:var(--code-bg);
  border:1px solid var(--sep)
}
.u.bubble .md code{
  background:rgba(0,0,0,.18);
  border-color:rgba(255,255,255,.16);
  color:#fff
}
.md pre{
  margin:1rem 0;
  padding:0;
  overflow:auto;
  border-radius:1rem;
  border:1px solid var(--sep);
  background:var(--code-bg)
}
.md pre code{
  display:block;
  padding:1rem;
  border:0;
  border-radius:0;
  background:transparent;
  font-size:.9rem;
  line-height:1.58
}
.u.bubble .md pre{
  background:rgba(0,0,0,.24);
  border-color:rgba(255,255,255,.12)
}
.md table{
  width:100%;
  border-collapse:collapse;
  margin:1rem 0;
  overflow:hidden;
  border-radius:1rem;
  border:1px solid var(--sep)
}
.md th,.md td{
  padding:.75rem .8rem;
  border-bottom:1px solid var(--sep);
  border-right:1px solid var(--sep);
  text-align:left;
  vertical-align:top
}
.md tr > *:last-child{border-right:0}
.md thead th{
  background:var(--table-head);
  font-size:var(--text-sm)
}
.md tbody tr:last-child td{border-bottom:0}
.md img{
  border-radius:1rem;
  margin:1rem 0;
  border:1px solid var(--sep)
}
.sources{
  display:flex;
  flex-wrap:wrap;
  gap:.5rem;
  margin:.8rem 0 .2rem
}
.src-chip,
.search-chip{
  display:inline-flex;
  align-items:center;
  gap:.42rem;
  min-height:32px;
  max-width:100%;
  padding:.25rem .65rem;
  border-radius:999px;
  border:1px solid var(--sep);
  color:var(--fg-2);
  font-size:var(--text-xs);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis
}
.search-chip.live{
  border-color:color-mix(in srgb,var(--accent) 22%,var(--sep));
  background:color-mix(in srgb,var(--accent) 10%,transparent)
}
.typing{
  display:inline-flex;
  align-items:flex-end;
  gap:.28rem;
  padding:.25rem 0 .1rem
}
.typing span{
  width:.45rem;
  height:.45rem;
  border-radius:50%;
  background:currentColor;
  opacity:.34;
  animation:tbounce 1.2s infinite ease-in-out
}
.typing span:nth-child(2){animation-delay:.14s}
.typing span:nth-child(3){animation-delay:.28s}
#ib-wrap{
  position:relative;
  padding:0 clamp(var(--space-3),4vw,var(--space-8)) calc(var(--space-3) + var(--safe-bottom));
  z-index:12
}
#ib-inner{
  width:min(100%,920px);
  margin:0 auto;
  display:grid;
  gap:.7rem
}
#img-strip{
  display:none;
  grid-auto-flow:column;
  grid-auto-columns:max-content;
  gap:.6rem;
  overflow:auto;
  padding:.15rem .15rem .2rem;
  scrollbar-width:thin
}
#img-strip.active{display:grid}
.attachment-chip{
  position:relative;
  display:grid;
  grid-template-columns:auto 1fr auto;
  align-items:center;
  gap:.55rem;
  min-height:58px;
  max-width:min(78vw,360px);
  padding:.45rem .55rem;
  border-radius:1rem;
  border:1px solid var(--sep);
  background:var(--liquid-2)
}
.attachment-thumb{
  width:46px;
  height:46px;
  border-radius:.8rem;
  overflow:hidden;
  border:1px solid var(--sep);
  background:var(--bg-soft);
  display:grid;
  place-items:center;
  flex:none
}
.attachment-thumb img{width:100%;height:100%;object-fit:cover}
.attachment-text{
  min-width:0;
  display:grid;
  gap:.15rem
}
.attachment-text strong{
  font-size:var(--text-sm);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis
}
.attachment-text span{
  font-size:var(--text-xs);
  color:var(--fg-3);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis
}
.attachment-remove{
  min-width:32px;
  min-height:32px;
  border-radius:.8rem;
  border:1px solid var(--sep);
  background:transparent
}
.input-shell{
  display:grid;
  grid-template-columns:auto 1fr auto;
  align-items:end;
  gap:.55rem;
  padding:.55rem;
  border-radius:1.45rem;
  border:1px solid var(--input-sep);
  background:var(--input-bg);
  box-shadow:var(--shadow-md);
  min-height:64px
}
#btn-gal{
  align-self:end
}
#ta{
  width:100%;
  min-height:52px;
  max-height:min(42svh,300px);
  resize:none;
  border:0;
  outline:0;
  background:transparent;
  color:var(--fg);
  padding:.7rem .15rem .75rem;
  line-height:1.45
}
#ta::placeholder{color:var(--fg-3)}
.sbtn{
  align-self:end;
  border-radius:1rem;
  min-width:52px;
  min-height:52px;
  background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 78%,white 4%),color-mix(in srgb,var(--accent-2) 76%,var(--accent-3) 14%));
  color:#fff;
  border-color:transparent;
  box-shadow:0 10px 30px color-mix(in srgb,var(--accent) 26%,transparent)
}
.sbtn[disabled]{
  opacity:.55;
  cursor:not-allowed;
  box-shadow:none
}
.file-input{
  display:none
}
#toasts{
  position:fixed;
  right:max(1rem,var(--safe-right));
  bottom:calc(1rem + var(--safe-bottom));
  z-index:60;
  display:grid;
  gap:.7rem;
  width:min(92vw,420px)
}
.toast{
  display:flex;
  align-items:flex-start;
  gap:.7rem;
  padding:.9rem 1rem;
  border-radius:1rem;
  color:var(--toast-fg);
  background:var(--toast-bg);
  border:1px solid color-mix(in srgb,var(--toast-bg) 72%,var(--sep));
  box-shadow:var(--shadow-lg);
  animation:tin .28s cubic-bezier(.16,1,.3,1)
}
.toast strong{display:block;font-size:var(--text-sm)}
.toast span{display:block;font-size:var(--text-xs);opacity:.86}
.toast .ticon{
  width:22px;
  height:22px;
  flex:none
}
#action-sheet{
  position:fixed;
  inset:auto 0 0 0;
  z-index:55;
  padding:0 max(var(--space-4),var(--safe-right)) max(var(--space-4),var(--safe-bottom)) max(var(--space-4),var(--safe-left));
  transform:translateY(110%);
  transition:transform .32s cubic-bezier(.16,1,.3,1);
  pointer-events:none
}
#action-sheet.open{
  transform:translateY(0);
  pointer-events:auto
}
.sheet{
  margin:0 auto;
  width:min(100%,560px);
  border-radius:1.5rem;
  border:1px solid var(--sep);
  background:var(--sheet-bg);
  box-shadow:var(--shadow-lg);
  overflow:hidden
}
.sheet-handle{
  width:3rem;
  height:4px;
  border-radius:999px;
  background:color-mix(in srgb,var(--fg-3) 35%,transparent);
  margin:.7rem auto .25rem
}
.sheet-body{
  padding:.35rem .55rem .6rem;
  display:grid;
  gap:.2rem
}
.sheet-title{
  padding:.35rem .75rem .5rem;
  font-size:var(--text-sm);
  color:var(--fg-3)
}
.sheet-btn{
  width:100%;
  justify-content:flex-start;
  border-radius:1rem;
  border-color:transparent;
  min-height:52px;
  padding:0 1rem
}
#ctx-menu{
  position:fixed;
  top:0;
  left:0;
  z-index:58;
  min-width:200px;
  max-width:min(90vw,280px);
  padding:.4rem;
  border-radius:1rem;
  border:1px solid var(--sep);
  background:var(--ctx-bg);
  box-shadow:var(--shadow-lg);
  transform:translate(-9999px,-9999px);
  opacity:0;
  pointer-events:none;
  display:grid;
  gap:.15rem
}
#ctx-menu.open{
  opacity:1;
  pointer-events:auto
}
.ctx-item{
  width:100%;
  justify-content:flex-start;
  border-radius:.9rem;
  border-color:transparent;
  min-height:42px;
  padding:0 .85rem
}
.ctx-item.danger{color:var(--err)}
.lg,
.bubble,
#sidebar,
.glass-panel,
#ib-inner > .input-shell,
.topbar,
.sheet,
.toast,
#ctx-menu{
  backdrop-filter:none;
  -webkit-backdrop-filter:none
}
.glass-host-override,
.glass-host-override *{
  background:transparent!important;
  border-color:transparent!important;
  box-shadow:none!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important
}
.empty-state{
  width:min(100%,760px);
  margin:10vh auto 0;
  display:grid;
  gap:1rem;
  justify-items:center;
  text-align:center;
  color:var(--fg-2)
}
.empty-state .hero-orb{
  width:min(48vw,220px);
  aspect-ratio:1;
  border-radius:50%;
  border:1px solid var(--sep);
  box-shadow:0 20px 80px var(--glow-a),inset 0 1px 0 rgba(255,255,255,.22)
}
.empty-state h1{
  font-size:var(--text-xl);
  margin:0
}
.empty-state p{
  max-width:48ch;
  margin:0
}
.meta-row{
  display:flex;
  flex-wrap:wrap;
  gap:.5rem;
  justify-content:center
}
.spinner{
  width:20px;
  height:20px;
  border-radius:50%;
  border:2px solid color-mix(in srgb,var(--fg-3) 32%,transparent);
  border-top-color:currentColor;
  animation:spin .9s linear infinite
}
@keyframes tbounce{
  0%,80%,100%{transform:translateY(0);opacity:.3}
  40%{transform:translateY(-.32rem);opacity:1}
}
@keyframes spin{
  to{transform:rotate(360deg)}
}
@keyframes tin{
  from{opacity:0;transform:translateY(10px) scale(.98)}
  to{opacity:1;transform:translateY(0) scale(1)}
}
.hljs{background:transparent!important}
@media (max-width:1024px){
  #sidebar{
    position:fixed;
    inset:0 auto 0 0;
    transform:translateX(-100%);
    width:min(var(--sidebar-w),88vw)
  }
  body.sidebar-open #sidebar{transform:translateX(0)}
  #app{
    grid-template-columns:1fr
  }
}
@media (min-width:1025px){
  .scrim{display:none}
  #btn-menu{display:none}
}
@media (max-width:640px){
  .topbar{
    padding:var(--space-3)
  }
  #msg-list{
    padding-inline:var(--space-3)
  }
  #ib-wrap{
    padding-inline:var(--space-3)
  }
  .input-shell{
    grid-template-columns:auto 1fr auto
  }
  .msg{
    margin-bottom:var(--space-4)
  }
  .md h1{font-size:1.45rem}
  .md h2{font-size:1.28rem}
  .md h3{font-size:1.15rem}
}
@media (prefers-reduced-motion:reduce){
  *,
  *::before,
  *::after{
    animation-duration:.01ms!important;
    animation-iteration-count:1!important;
    transition-duration:.01ms!important;
    scroll-behavior:auto!important
  }
}
</style>
