<body>
<canvas id="glass-renderer-canvas" aria-hidden="true"></canvas>
<div class="scrim" id="scrim" aria-hidden="true"></div>
<div id="app">
  <aside id="sidebar" class="sidebar lg" aria-label="Conversation history">
    <div class="sb-head">
      <div class="sb-pull-indicator" aria-hidden="true"></div>
      <div class="brand-row">
        <div class="brand">
          <div class="logo" aria-hidden="true">
            <svg viewBox="0 0 64 64" fill="none">
              <path d="M14 40.5C14 22.998 27.998 9 45.5 9H55v9.5C55 36.002 41.002 50 23.5 50H14v-9.5Z" stroke="currentColor" stroke-width="5" stroke-linejoin="round"/>
              <path d="M21 55c3-12 13.5-22.5 28-28" stroke="currentColor" stroke-width="5" stroke-linecap="round"/>
            </svg>
          </div>
          <div class="brand-copy">
            <strong>Glass AI</strong>
            <span>Local-first advanced chat</span>
          </div>
        </div>
        <div class="head-actions">
          <button class="theme-btn" id="theme-toggle" type="button" aria-label="Toggle theme"></button>
        </div>
      </div>
      <button id="btn-sb-new" class="action-btn" type="button">
        <span id="btn-sb-new-icon" aria-hidden="true"></span>
        <span>New chat</span>
      </button>
      <div id="sb-search-wrap">
        <span id="sb-search-icon" aria-hidden="true"></span>
        <input id="sb-search-bar" type="search" inputmode="search" autocomplete="off" spellcheck="false" placeholder="Search conversations">
      </div>
    </div>
    <ul id="hlist" aria-label="Chat history"></ul>
  </aside>

  <main id="content" aria-label="Chat window">
    <header class="topbar lg">
      <div class="topbar-left">
        <button id="btn-menu" class="icon-btn" type="button" aria-label="Toggle sidebar"></button>
        <div class="top-title">
          <strong id="conv-title">New chat</strong>
          <span id="conv-status">Ready</span>
        </div>
      </div>
