        <button id="btn-clear" class="icon-btn" type="button" aria-label="Conversation actions"></button>
      </div>
    </header>

    <section id="msg-wrap" aria-live="polite">
      <div id="msg-list"></div>
    </section>

    <section id="ib-wrap" aria-label="Compose">
      <div id="ib-inner">
        <div id="img-strip" aria-live="polite"></div>
        <div class="input-shell lg glass-panel">
          <button id="btn-gal" class="icon-btn" type="button" aria-label="Attach image or file"></button>
          <textarea id="ta" rows="1" placeholder="Message Glass AI" enterkeyhint="send"></textarea>
          <button id="sbtn" class="sbtn" type="button" aria-label="Send message"></button>
        </div>
      </div>
      <input class="file-input" id="file-input" type="file" accept="image/*,.txt,.md,.json,.csv,.js,.ts,.html,.css,.xml,.yaml,.yml,.log,.pdf" multiple>
    </section>
  </main>
</div>

<div id="toasts" aria-live="polite" aria-atomic="false"></div>

<div id="action-sheet" aria-hidden="true">
  <div class="sheet lg" role="dialog" aria-modal="true" aria-labelledby="sheet-title">
    <div class="sheet-handle" aria-hidden="true"></div>
    <div id="sheet-title" class="sheet-title">Actions</div>
    <div class="sheet-body" id="sheet-body"></div>
  </div>
</div>

<div id="ctx-menu" role="menu" aria-hidden="true">
  <button class="ctx-item" type="button" data-act="copy"></button>
  <button class="ctx-item" type="button" data-act="edit"></button>
  <button class="ctx-item danger" type="button" data-act="delete"></button>
</div>

