  const safeStore = {
    get(key, fallback){
      if(!supportsStorage) return fallback;
      try{
        const raw = localStorage.getItem(key);
        return raw ? JSON.parse(raw) : fallback;
      }catch{
        return fallback;
      }
    },
    set(key, value){
      if(!supportsStorage) return;
      try{
