  function uid(prefix="id"){
    const rand = Math.random().toString(36).slice(2,10);
    return prefix + "_" + Date.now().toString(36) + rand;
  }

  function clamp(v,min,max){
    return Math.max(min, Math.min(max, v));
  }

  function timeNow(){
    return Date.now();
  }

  function formatTime(ts){
    const d = new Date(ts);
    return new Intl.DateTimeFormat(undefined,{hour:"2-digit",minute:"2-digit"}).format(d);
  }

  function formatDateCompact(ts){
    const d = new Date(ts);
    return new Intl.DateTimeFormat(undefined,{month:"short",day:"numeric"}).format(d);
  }

  function escapeHtml(str){
    return String(str).replace(/[&<>"']/g, m => ({'&':"&amp;",'<':"&lt;",'>':"&gt;",'"':"&quot;","'":"&#39;"}[m]));
  }

  function sanitizeUrl(url){
    try{
      const u = new URL(url, location.href);
      if(["http:","https:","data:"].includes(u.protocol)) return u.href;
    }catch{}
    return "";
  }

  function copyText(text){
    if(navigator.clipboard?.writeText){
      return navigator.clipboard.writeText(text);
    }
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    try{document.execCommand("copy")}catch{}
    ta.remove();
    return Promise.resolve();
  }

  function showToast(title, text="", kind="info", timeout=2600){
    const t = document.createElement("div");
    t.className = "toast lg";
    const icon = kind === "error" ? svgIcon.alert : svgIcon.check;
    t.innerHTML = `<div class="ticon">${icon}</div><div><strong>${escapeHtml(title)}</strong><span>${escapeHtml(text)}</span></div>`;
    toasts.appendChild(t);
    setTimeout(() => {
      t.style.opacity = "0";
      t.style.transform = "translateY(8px)";
      setTimeout(() => t.remove(), 200);
    }, timeout);
  }

  function defaultChats(){
    const now = timeNow();
    const chatId = uid("chat");
    return [{
      id:chatId,
      title:"New chat",
      pinned:false,
      createdAt:now,
      updatedAt:now,
      lastSnippet:"",
      sessionId:null,
      activeJobId:null,
      messages:[]
    }];
  }

  function loadChats(){
    const meta = safeStore.get(STORAGE_KEYS.meta, null);
    if(meta && Array.isArray(meta.chats) && meta.chats.length){
      state.chats = meta.chats.map(chat => ({
        id:chat.id || uid("chat"),
        title:chat.title || "Untitled",
        pinned:!!chat.pinned,
        createdAt:chat.createdAt || timeNow(),
        updatedAt:chat.updatedAt || timeNow(),
        lastSnippet:chat.lastSnippet || "",
        sessionId:chat.sessionId || null,
        activeJobId:chat.activeJobId || null,
        messages:Array.isArray(chat.messages) ? chat.messages.filter(m => !state.deleted.has(m.id)).map(m => ({
          id:m.id || uid("msg"),
          role:m.role === "user" ? "user" : "assistant",
          text:typeof m.text === "string" ? m.text : "",
          html:typeof m.html === "string" ? m.html : "",
          createdAt:m.createdAt || timeNow(),
          attachments:Array.isArray(m.attachments) ? m.attachments : [],
          sources:Array.isArray(m.sources) ? m.sources : [],
          searchChips:Array.isArray(m.searchChips) ? m.searchChips : [],
          pending:!!m.pending,
          edited:!!m.edited
        })) : []
      }));
    }else{
      state.chats = defaultChats();
    }
    if(!state.chats.length) state.chats = defaultChats();
    state.currentId = state.chats[0].id;
  }

  function persistChats(){
    safeStore.set(STORAGE_KEYS.meta,{
      chats:state.chats
    });
    safeStore.set(STORAGE_KEYS.deleted, [...state.deleted]);
  }

  function getCurrentChat(){
    let chat = state.chats.find(c => c.id === state.currentId);
    if(!chat){
      chat = state.chats[0];
      state.currentId = chat?.id || null;
    }
    return chat;
  }

  function sortChats(chats){
    return [...chats].sort((a,b) => {
      if(!!a.pinned !== !!b.pinned) return a.pinned ? -1 : 1;
      return (b.updatedAt || 0) - (a.updatedAt || 0);
    });
  }

  function updateChatTitle(chat){
    const firstUser = chat.messages.find(m => m.role === "user");
    const raw = firstUser?.text?.trim() || "New chat";
    chat.title = raw.slice(0,56) || "New chat";
    const last = [...chat.messages].reverse().find(m => m.text?.trim());
    chat.lastSnippet = last ? last.text.trim().slice(0,92) : "";
    chat.updatedAt = timeNow();
  }

  function newChat(){
    const c = {
      id:uid("chat"),
      title:"New chat",
      pinned:false,
      createdAt:timeNow(),
      updatedAt:timeNow(),
      lastSnippet:"",
      sessionId:null,
      activeJobId:null,
      messages:[]
    };
    state.chats.unshift(c);
    state.currentId = c.id;
    state.attachments = [];
    state.pendingAssistantId = null;
    renderAttachments();
    renderHistory();
    renderConversation();
    persistChats();
    closeSidebar();
    ta.focus();
  }

  function deleteMessage(chatId, msgId){
    const chat = state.chats.find(c => c.id === chatId);
    if(!chat) return;
    chat.messages = chat.messages.filter(m => m.id !== msgId);
    state.deleted.add(msgId);
    updateChatTitle(chat);
    persistChats();
    renderHistory();
    renderConversation();
    showToast("Message deleted");
  }

  function deleteConversation(chatId){
    const idx = state.chats.findIndex(c => c.id === chatId);
    if(idx < 0) return;
    const removed = state.chats.splice(idx,1)[0];
    removed.messages.forEach(m => state.deleted.add(m.id));
    if(!state.chats.length) state.chats = defaultChats();
    state.currentId = state.chats[0].id;
    persistChats();
    renderHistory();
    renderConversation();
    showToast("Conversation deleted");
  }

  function pinConversation(chatId){
    const chat = state.chats.find(c => c.id === chatId);
    if(!chat) return;
    chat.pinned = !chat.pinned;
    chat.updatedAt = timeNow();
    persistChats();
    renderHistory();
  }

