  function markdownInline(text){
    let safe = escapeHtml(text);
    safe = safe.replace(/`([^`\n]+)`/g, "<code>$1</code>");
    safe = safe.replace(/\*\*([^\n*][\s\S]*?)\*\*/g, "<strong>$1</strong>");
    safe = safe.replace(/(^|[^*])\*([^*\n][\s\S]*?)\*(?!\*)/g, "$1<em>$2</em>");
    safe = safe.replace(/(^|[^_])_([^_\n][\s\S]*?)_(?!_)/g, "$1<em>$2</em>");
    safe = safe.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_, label, href) => {
      const u = sanitizeUrl(href);
      return u ? `${label}` : label;
    });
    return safe;
  }

  function parseMarkdown(md){
    const src = String(md || "").replace(/\r\n?/g,"\n");
    const lines = src.split("\n");
    const out = [];
    let i = 0;
    const closeList = listType => {
      if(listType) out.push(`</${listType}>`);
      return null;
    };
    let listType = null;

    while(i < lines.length){
      const line = lines[i];
      const next = lines[i + 1] || "";

      if(/^```/.test(line)){
        listType = closeList(listType);
        const lang = line.slice(3).trim().toLowerCase();
        let code = [];
        i++;
        while(i < lines.length && !/^```/.test(lines[i])){
          code.push(lines[i]);
          i++;
        }
        out.push(`<pre><code class="language-${escapeHtml(lang || "plaintext")}">${escapeHtml(code.join("\n"))}</code></pre>`);
        i++;
        continue;
      }

      if(/^\s*$/.test(line)){
        listType = closeList(listType);
        i++;
        continue;
      }

      if(/^\s*---+\s*$/.test(line)){
        listType = closeList(listType);
        out.push("<hr>");
        i++;
        continue;
      }

      const heading = line.match(/^(#{1,6})\s+(.*)$/);
      if(heading){
        listType = closeList(listType);
        const level = heading[1].length;
        out.push(`<h${level}>${markdownInline(heading[2].trim())}</h${level}>`);
        i++;
        continue;
      }

      const quote = line.match(/^>\s?(.*)$/);
      if(quote){
        listType = closeList(listType);
        const buff = [quote[1]];
        i++;
        while(i < lines.length){
          const q = lines[i].match(/^>\s?(.*)$/);
          if(!q) break;
          buff.push(q[1]);
          i++;
        }
        out.push(`<blockquote>${buff.map(v => `<p>${markdownInline(v)}</p>`).join("")}</blockquote>`);
        continue;
      }

      const ul = line.match(/^\s*[-*+]\s+(.*)$/);
      const ol = line.match(/^\s*(\d+)\.\s+(.*)$/);
      if(ul || ol){
        const target = ul ? "ul" : "ol";
        if(listType !== target){
          listType = closeList(listType);
          listType = target;
          out.push(`<${target}>`);
        }
        out.push(`<li>${markdownInline((ul || ol)[1] || (ul || ol)[2])}</li>`);
        i++;
        continue;
      }

      if(/\|/.test(line) && /^\s*\|?(.+\|)+.+\|?\s*$/.test(line) && /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(next)){
        listType = closeList(listType);
        const head = splitTableRow(line);
        const rows = [];
        i += 2;
        while(i < lines.length && /\|/.test(lines[i])){
          rows.push(splitTableRow(lines[i]));
          i++;
        }
        out.push(`<table><thead><tr>${head.map(c => `<th>${markdownInline(c)}</th>`).join("")}</tr></thead><tbody>${rows.map(r => `<tr>${head.map((_, idx) => `<td>${markdownInline(r[idx] || "")}</td>`).join("")}</tr>`).join("")}</tbody></table>`);
        continue;
      }

      listType = closeList(listType);
      const para = [line];
      i++;
      while(i < lines.length && lines[i].trim() && !/^(#{1,6})\s+/.test(lines[i]) && !/^```/.test(lines[i]) && !/^\s*[-*+]\s+/.test(lines[i]) && !/^\s*\d+\.\s+/.test(lines[i]) && !/^>\s?/.test(lines[i]) && !/^\s*---+\s*$/.test(lines[i])){
        if(/\|/.test(lines[i]) && /^\s*\|?(.+\|)+.+\|?\s*$/.test(lines[i]) && /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(lines[i + 1] || "")) break;
        para.push(lines[i]);
        i++;
      }
      out.push(`<p>${markdownInline(para.join(" ").trim())}</p>`);
    }
    closeList(listType);
    return out.join("");
  }

  function splitTableRow(line){
    let s = line.trim();
    if(s.startsWith("|")) s = s.slice(1);
    if(s.endsWith("|")) s = s.slice(0,-1);
    return s.split("|").map(v => v.trim());
  }

