  async function fileToDataUrl(file){
    return new Promise((resolve,reject) => {
      const r = new FileReader();
      r.onload = () => resolve(r.result);
      r.onerror = reject;
      r.readAsDataURL(file);
    });
  }

  async function fileToText(file){
    return new Promise((resolve,reject) => {
      const r = new FileReader();
      r.onload = () => resolve(String(r.result || ""));
      r.onerror = reject;
      r.readAsText(file);
    });
  }

  async function compressImageFile(file, maxDim=1600, quality=.84){
    const dataUrl = await fileToDataUrl(file);
    const img = new Image();
    img.decoding = "async";
    img.src = dataUrl;
    await img.decode();
    const scale = Math.min(1, maxDim / Math.max(img.naturalWidth, img.naturalHeight));
    const w = Math.max(1, Math.round(img.naturalWidth * scale));
    const h = Math.max(1, Math.round(img.naturalHeight * scale));
    const c = document.createElement("canvas");
    c.width = w;
    c.height = h;
    const ctx = c.getContext("2d",{alpha:false});
    ctx.drawImage(img,0,0,w,h);
    let out = c.toDataURL("image/jpeg", quality);
    if(out.length > 2_500_000){
      out = c.toDataURL("image/jpeg", .72);
    }
    return {dataUrl:out,width:w,height:h};
  }

  async function addFiles(files){
    const incoming = Array.from(files || []);
    if(!incoming.length) return;
    for(const file of incoming){
      if(file.type.startsWith("image/")){
        try{
          const compressed = await compressImageFile(file);
          state.attachments.push({
            id:uid("att"),
            kind:"image",
            name:file.name || "image.jpg",
            mime:"image/jpeg",
            dataUrl:compressed.dataUrl,
            width:compressed.width,
            height:compressed.height,
            size:file.size
          });
        }catch{
          showToast("Image failed", file.name || "Could not process image", "error");
        }
      }else{
        try{
          const text = await fileToText(file);
          state.attachments.push({
            id:uid("att"),
            kind:"text",
            name:file.name || "file.txt",
            mime:file.type || "text/plain",
            text
          });
        }catch{
          showToast("File failed", file.name || "Could not read file", "error");
        }
      }
    }
    renderAttachments();
    showToast("Attached", `${incoming.length} file${incoming.length === 1 ? "" : "s"} ready`);
  }

