  async function handleSend(){
    const content = ta.value.trim();
    if(!content && !state.attachments.length) return;
    if(state.activeAbort){
      showToast("Wait", "A response is already streaming", "error");
      return;
    }
    const chat = getCurrentChat();
    const sentAttachments = state.attachments.map(v => ({...v}));
    const userText = content + buildUserAttachmentText(sentAttachments);
    pushMessage("user", userText, {attachments:sentAttachments});
    ta.value = "";
    state.attachments = [];
    renderAttachments();
    autoResizeTextarea();
    closeSidebar();
    const assistant = pushMessage("assistant", "", {pending:true});
    state.pendingAssistantId = assistant.id;
