  async function streamChat(chat, assistantId){
    const assistant = chat.messages.find(m => m.id === assistantId);
    if(!assistant) return;
    const controller = new AbortController();
    state.activeAbort = controller;
    setPendingUi(true);

    const payload = {
      conversation_id:chat.id,
      session_id:chat.sessionId,
      messages:chat.messages.filter(m => m.id !== assistantId).map(m => ({
        role:m.role,
        content:m.role === "user" ? m.text : m.text
      })),
      attachments:state.attachments
    };

    let attempt = 0;
    let delay = 700;
    while(attempt < 5){
      try{
        await fetchSSE("/api/chat",{
          method:"POST",
          headers:{"Content-Type":"application/json","Accept":"text/event-stream"},
          body:JSON.stringify(payload),
          signal:controller.signal
        }, evt => {
          processSseEvent(chat, assistant, evt);
        });
        assistant.pending = false;
        chat.activeJobId = null;
        updateChatTitle(chat);
        persistChats();
        renderConversation();
        break;
      }catch(err){
        if(controller.signal.aborted) break;
        attempt++;
        if(attempt >= 5){
          assistant.pending = false;
          assistant.text += assistant.text ? `\n\n` : "";
          assistant.text += "Network error. The request failed after multiple retries.";
          assistant.html = parseMarkdown(assistant.text);
          updateChatTitle(chat);
          persistChats();
          renderConversation();
          showToast("Request failed", "Unable to reach /api/chat", "error", 3600);
          break;
        }
        convStatus.textContent = `Retrying in ${Math.round(delay / 1000)}s`;
        await new Promise(r => setTimeout(r, delay));
        delay = Math.min(delay * 2, 8000);
      }
    }

    state.activeAbort = null;
    setPendingUi(false);
  }

  async function fetchSSE(url, options, onEvent){
    const res = await fetch(url, options);
    if(!res.ok) throw new Error(`HTTP ${res.status}`);
    if(!res.body) throw new Error("ReadableStream unavailable");
    const reader = res.body.getReader();
    const decoder = new TextDecoder("utf-8");
    let buffer = "";
    while(true){
      const {value, done} = await reader.read();
      if(done) break;
      buffer += decoder.decode(value,{stream:true});
      let boundary;
      while((boundary = buffer.indexOf("\n\n")) !== -1){
        const raw = buffer.slice(0,boundary);
        buffer = buffer.slice(boundary + 2);
        const evt = parseSseBlock(raw);
        if(evt) onEvent(evt);
      }
    }
    if(buffer.trim()){
      const evt = parseSseBlock(buffer);
      if(evt) onEvent(evt);
    }
  }

  function parseSseBlock(block){
    const lines = block.split(/\n/);
    let event = "message";
    const data = [];
    for(const line of lines){
      if(line.startsWith(":")) continue;
      if(line.startsWith("event:")) event = line.slice(6).trim();
      else if(line.startsWith("data:")) data.push(line.slice(5).trimStart());
    }
    const joined = data.join("\n");
    if(!joined && event === "message") return null;
    let parsed = joined;
    try{ parsed = JSON.parse(joined); }catch{}
    return {event,data:parsed};
  }

  function ensureAssistantMessage(chat, msgId){
    let msg = chat.messages.find(m => m.id === msgId);
    if(!msg){
      msg = pushMessage("assistant","",{pending:true});
    }
    return msg;
  }

  function processSseEvent(chat, assistant, evt){
    assistant = ensureAssistantMessage(chat, assistant.id);
    const d = evt.data;
    if(evt.event === "session"){
      chat.sessionId = typeof d === "string" ? d : d?.id || d?.session || chat.sessionId;
      chipModel.textContent = chat.sessionId ? `session ${chat.sessionId}` : chipModel.textContent;
    }else if(evt.event === "job_id"){
      chat.activeJobId = typeof d === "string" ? d : d?.job_id || d?.id || null;
      state.currentJobId = chat.activeJobId;
      convStatus.textContent = chat.activeJobId ? "Background job active" : "Streaming response";
    }else if(evt.event === "search_start"){
      const label = typeof d === "string" ? d : d?.query || d?.label || "Searching";
      assistant.searchChips = assistant.searchChips || [];
      assistant.searchChips.push({label, live:true});
    }else if(evt.event === "sources"){
      const sources = Array.isArray(d) ? d : Array.isArray(d?.sources) ? d.sources : [d].filter(Boolean);
      assistant.sources = assistant.sources || [];
      sources.forEach(src => {
        if(!src) return;
        const title = src.title || src.name || src.label || src.url || "Source";
        assistant.sources.push({title,url:src.url || ""});
      });
    }else if(evt.event === "content" || evt.event === "message"){
      const chunk = typeof d === "string" ? d : d?.text || d?.content || "";
      assistant.text += chunk;
      assistant.html = parseMarkdown(assistant.text);
      if(assistant.searchChips?.length){
        assistant.searchChips = assistant.searchChips.map(v => ({...v,live:false}));
      }
    }else if(evt.event === "done" || evt.event === "complete"){
      assistant.pending = false;
      chat.activeJobId = null;
      if(assistant.searchChips?.length){
        assistant.searchChips = assistant.searchChips.map(v => ({...v,live:false}));
      }
    }else if(evt.event === "error"){
      assistant.pending = false;
      const message = typeof d === "string" ? d : d?.error || d?.message || "Unknown error";
      assistant.text += (assistant.text ? "\n\n" : "") + `Error: ${message}`;
      assistant.html = parseMarkdown(assistant.text);
      showToast("Server error", message, "error", 3600);
    }
    updateChatTitle(chat);
    persistChats();
    renderConversation();
    if(!state.autoScrollLock) scrollToBottom(true);
  }

  async function checkResumeForChat(chat){
    let changed = false;
    if(chat.activeJobId){
      try{
        const res = await fetch(`/api/job/${encodeURIComponent(chat.activeJobId)}/status`,{headers:{Accept:"application/json"}});
        if(res.ok){
          const data = await res.json();
          if(data?.done || data?.status === "done" || data?.status === "completed"){
            chat.activeJobId = null;
            changed = true;
          }else if(data?.resume_id || data?.session_id || chat.sessionId){
            const rid = data.resume_id || chat.sessionId || data.session_id;
            const res2 = await fetch(`/api/agent/resume/${encodeURIComponent(rid)}`,{
              method:"POST",
              headers:{Accept:"text/event-stream"}
            });
            if(res2.ok && res2.body){
              const assistant = pushMessage("assistant","",{pending:true});
              state.pendingAssistantId = assistant.id;
              await fetchSSE(`/api/agent/resume/${encodeURIComponent(rid)}`,{
                method:"POST",
                headers:{Accept:"text/event-stream"}
              }, evt => processSseEvent(chat, assistant, evt));
              changed = true;
            }
          }
        }
      }catch{}
    }else if(chat.sessionId){
      try{
        const res = await fetch(`/api/agent/resume/${encodeURIComponent(chat.sessionId)}`,{
          method:"POST",
          headers:{Accept:"text/event-stream"}
        });
        if(res.ok && res.body){
          const assistant = pushMessage("assistant","",{pending:true});
          state.pendingAssistantId = assistant.id;
          await fetchSSE(`/api/agent/resume/${encodeURIComponent(chat.sessionId)}`,{
            method:"POST",
            headers:{Accept:"text/event-stream"}
          }, evt => processSseEvent(chat, assistant, evt));
          changed = true;
        }
      }catch{}
    }
    if(changed){
      updateChatTitle(chat);
      persistChats();
      renderConversation();
    }
  }

