  function touchStart(e){
    if(!e.touches?.length) return;
    const t = e.touches[0];
    state.gesture.active = true;
    state.gesture.x = t.clientX;
    state.gesture.y = t.clientY;
    state.gesture.dx = 0;
    state.gesture.dy = 0;
    state.gesture.sidebarPull = e.target.closest("#hlist") && hlist.scrollTop <= 0;
    state.gesture.pullStartY = t.clientY;
    state.gesture.pullDistance = 0;
  }

  function touchMove(e){
    if(!state.gesture.active || !e.touches?.length) return;
    const t = e.touches[0];
    state.gesture.dx = t.clientX - state.gesture.x;
    state.gesture.dy = t.clientY - state.gesture.y;

    if(window.innerWidth <= 1024){
      const nearLeft = state.gesture.x < 24;
      if(Math.abs(state.gesture.dx) > Math.abs(state.gesture.dy) && nearLeft && state.gesture.dx > 24 && !body.classList.contains("sidebar-open")){
        openSidebar();
      }
      if(Math.abs(state.gesture.dx) > Math.abs(state.gesture.dy) && body.classList.contains("sidebar-open") && state.gesture.dx < -24){
        closeSidebar();
      }
    }

    if(state.gesture.sidebarPull && state.gesture.dy > 0){
      state.gesture.pullDistance = clamp(state.gesture.dy, 0, 86);
      const wrap = $("#sb-search-wrap");
      wrap.style.transform = `translateY(${state.gesture.pullDistance * .22}px) scale(${1 + state.gesture.pullDistance * .0014})`;
      wrap.style.opacity = String(clamp(.72 + state.gesture.pullDistance / 120, .72, 1));
    }
  }

  function touchEnd(){
    if(state.gesture.sidebarPull){
      const wrap = $("#sb-search-wrap");
      if(state.gesture.pullDistance > 34) searchBar.focus();
      wrap.style.transform = "";
      wrap.style.opacity = "";
    }
    state.gesture.active = false;
    state.gesture.sidebarPull = false;
  }

  document.addEventListener("touchstart", touchStart, {passive:true});
  document.addEventListener("touchmove", touchMove, {passive:true});
  document.addEventListener("touchend", touchEnd, {passive:true});

  class MultiPassRenderer{
    constructor(canvas){
      this.canvas = canvas;
      this.gl = canvas.getContext("webgl2",{antialias:true,alpha:true,premultipliedAlpha:true,preserveDrawingBuffer:false});
      this.timeStart = performance.now();
      this.maxBoxes = 128;
      this.boxData = new Float32Array(this.maxBoxes * 4);
      this.radiusData = new Float32Array(this.maxBoxes);
      this.boxCount = 0;
      this.dpr = Math.min(devicePixelRatio || 1, 2);
      this.needsSync = true;
      this.ready = false;
      this.targets = [];
      this.lastRectsKey = "";
      if(!this.gl){
        canvas.style.display = "none";
        return;
      }
      const gl = this.gl;
      if(!gl.getExtension("EXT_color_buffer_float")){
        canvas.style.display = "none";
        return;
      }
      this.init();
      this.bind();
      this.resize();
      this.ready = true;
      this.frame();
    }
    onThemeChange(){
      this.requestSync();
    }
    requestSync(){
      this.needsSync = true;
    }
    bind(){
      addEventListener("resize", () => this.resize(), {passive:true});
      addEventListener("scroll", () => this.requestSync(), {passive:true});
      new MutationObserver(() => this.requestSync()).observe(document.body,{attributes:true,childList:true,subtree:true});
      if(window.ResizeObserver){
        const ro = new ResizeObserver(() => this.requestSync());
        ro.observe(document.body);
      }
    }
    resize(){
      if(!this.gl) return;
      const w = Math.max(1, Math.floor(innerWidth * this.dpr));
      const h = Math.max(1, Math.floor(innerHeight * this.dpr));
      if(this.canvas.width !== w || this.canvas.height !== h){
        this.canvas.width = w;
        this.canvas.height = h;
      }
      this.canvas.style.width = innerWidth + "px";
      this.canvas.style.height = innerHeight + "px";
      this.createTargets();
      this.requestSync();
    }
    init(){
      const gl = this.gl;
      this.quad = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, this.quad);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1,1,-1,-1,1,1,1]), gl.STATIC_DRAW);

      this.bgProg = this.program(this.vs(), this.fsBackground());
      this.blurProg = this.program(this.vs(), this.fsBlur());
      this.mainProg = this.program(this.vs(), this.fsMain());

      this.loc = {
        bg:{
          time:gl.getUniformLocation(this.bgProg,"uTime"),
          res:gl.getUniformLocation(this.bgProg,"uResolution"),
          theme:gl.getUniformLocation(this.bgProg,"uTheme")
        },
        blur:{
          src:gl.getUniformLocation(this.blurProg,"uTex"),
          dir:gl.getUniformLocation(this.blurProg,"uDirection"),
          res:gl.getUniformLocation(this.blurProg,"uResolution"),
          weights:gl.getUniformLocation(this.blurProg,"uWeights[0]"),
          radius:gl.getUniformLocation(this.blurProg,"uRadius")
        },
        main:{
          scene:gl.getUniformLocation(this.mainProg,"uScene"),
          blur:gl.getUniformLocation(this.mainProg,"uBlur"),
          res:gl.getUniformLocation(this.mainProg,"uResolution"),
          time:gl.getUniformLocation(this.mainProg,"uTime"),
          boxCount:gl.getUniformLocation(this.mainProg,"uBoxCount"),
          boxes:gl.getUniformLocation(this.mainProg,"uBoxes[0]"),
          radii:gl.getUniformLocation(this.mainProg,"uRadii[0]"),
          theme:gl.getUniformLocation(this.mainProg,"uTheme")
        }
      };
      this.weights = this.gaussianWeights(12, 8.2);
    }
    createTargets(){
      const gl = this.gl;
      const w = this.canvas.width;
      const h = this.canvas.height;
      const make = () => {
        const tex = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, tex);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA16F,w,h,0,gl.RGBA,gl.HALF_FLOAT,null);
        const fbo = gl.createFramebuffer();
        gl.bindFramebuffer(gl.FRAMEBUFFER,fbo);
        gl.framebufferTexture2D(gl.FRAMEBUFFER,gl.COLOR_ATTACHMENT0,gl.TEXTURE_2D,tex,0);
        return {tex,fbo};
      };
      this.scene = make();
      this.blurA = make();
      this.blurB = make();
      gl.bindFramebuffer(gl.FRAMEBUFFER,null);
    }
    gaussianWeights(radius, sigma){
      const arr = [];
      let sum = 0;
      for(let i=0;i<=radius;i++){
        const w = Math.exp(-(i*i)/(2*sigma*sigma));
        arr.push(w);
        sum += i === 0 ? w : w * 2;
      }
      return arr.map(v => v / sum);
    }
    vs(){
      return `#version 300 es
      in vec2 aPosition;
      out vec2 vUv;
      void main(){
        vUv = aPosition * .5 + .5;
        gl_Position = vec4(aPosition,0.,1.);
      }`;
    }
    fsBackground(){
      return `#version 300 es
      precision highp float;
      out vec4 outColor;
      in vec2 vUv;
      uniform vec2 uResolution;
      uniform float uTime;
      uniform float uTheme;
      float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}
      float noise(vec2 p){
        vec2 i=floor(p),f=fract(p);
        float a=hash(i),b=hash(i+vec2(1,0)),c=hash(i+vec2(0,1)),d=hash(i+vec2(1,1));
        vec2 u=f*f*(3.0-2.0*f);
        return mix(a,b,u.x)+(c-a)*u.y*(1.0-u.x)+(d-b)*u.x*u.y;
      }
      vec3 palette(float t,float dark){
        vec3 a = mix(vec3(.95,.97,1.0),vec3(.06,.08,.11),dark);
        vec3 b = mix(vec3(.26,.48,1.0),vec3(.42,.52,1.0),dark);
        vec3 c = mix(vec3(.46,.28,1.0),vec3(.48,.38,1.0),dark);
        vec3 d = mix(vec3(.12,.82,1.0),vec3(.18,.75,.95),dark);
        return a + .16*b*sin(6.2831*(t+.12)) + .13*c*sin(6.2831*(t+.42)) + .08*d*sin(6.2831*(t+.73));
      }
      void main(){
        vec2 uv=vUv;
        vec2 p=(gl_FragCoord.xy-.5*uResolution.xy)/uResolution.y;
        float t=uTime*.06;
        float n=0.;
        float amp=.5;
        vec2 q=p*2.2;
        for(int i=0;i<4;i++){
          n += noise(q + vec2(t*float(i+1), -t*1.3*float(i+1))) * amp;
          q*=1.93;
          amp*=.5;
        }
        float wave = .5 + .5*sin(p.x*2.4 + p.y*1.6 + uTime*.25 + n*2.8);
        float wave2 = .5 + .5*cos(length(p*vec2(1.1,.8))*4.2 - uTime*.19 + n*3.2);
        vec3 col = palette(.35*wave + .65*wave2, uTheme);
        float vign = smoothstep(1.45,.15,length(p));
        col *= mix(.88,1.08,vign);
        outColor = vec4(col,1.);
      }`;
    }
    fsBlur(){
      return `#version 300 es
      precision highp float;
      out vec4 outColor;
      in vec2 vUv;
      uniform sampler2D uTex;
      uniform vec2 uDirection;
      uniform vec2 uResolution;
      uniform float uWeights[13];
      uniform int uRadius;
      void main(){
        vec2 texel = 1.0 / uResolution;
        vec4 sum = texture(uTex, vUv) * uWeights[0];
        for(int i=1;i<13;i++){
          if(i>uRadius) break;
          vec2 off = uDirection * texel * float(i);
          sum += texture(uTex, vUv + off) * uWeights[i];
          sum += texture(uTex, vUv - off) * uWeights[i];
        }
        outColor = sum;
      }`;
    }
    fsMain(){
      return `#version 300 es
      precision highp float;
      out vec4 outColor;
      in vec2 vUv;
      uniform sampler2D uScene;
      uniform sampler2D uBlur;
      uniform vec2 uResolution;
      uniform float uTime;
      uniform int uBoxCount;
      uniform vec4 uBoxes[128];
      uniform float uRadii[128];
      uniform float uTheme;

      float sdRoundRect(vec2 p, vec2 b, float r){
        vec2 q = abs(p) - b + vec2(r);
        return length(max(q,0.0)) + min(max(q.x,q.y),0.0) - r;
      }

      float boxSdf(vec2 frag, vec4 rect, float radius){
        vec2 center = rect.xy + rect.zw * .5;
        vec2 halfSize = rect.zw * .5;
        return sdRoundRect(frag - center, halfSize, radius);
      }

      float sceneSdf(vec2 frag, out int idx){
        float d = 1e9;
        idx = -1;
        for(int i=0;i<128;i++){
          if(i>=uBoxCount) break;
          float di = boxSdf(frag, uBoxes[i], uRadii[i]);
          if(di < d){
            d = di;
            idx = i;
          }
        }
        return d;
      }

      vec2 sceneNormal(vec2 frag){
        int k;
        float e = 1.25;
        float dx = sceneSdf(frag + vec2(e,0.), k) - sceneSdf(frag - vec2(e,0.), k);
        float dy = sceneSdf(frag + vec2(0.,e), k) - sceneSdf(frag - vec2(0.,e), k);
        return normalize(vec2(dx,dy) + 1e-6);
      }

      void main(){
        vec2 frag = gl_FragCoord.xy;
        int idx;
        float d = sceneSdf(frag, idx);
        vec4 scene = texture(uScene, vUv);
        if(idx < 0){
          outColor = scene;
          return;
        }
        float edge = smoothstep(8.0, -2.0, d);
        float interior = smoothstep(0.0, -18.0, d);
        vec2 n = sceneNormal(frag);
        float fres = pow(1.0 - abs(dot(n, vec2(0.0, -1.0))), 2.8);
        vec2 uv = vUv + n * (.012 + fres * .012) * interior;
        vec3 refr = texture(uBlur, uv).rgb;
        vec3 under = texture(uScene, uv).rgb;
        vec3 col = mix(under, refr, .72);
        vec3 edgeTint = mix(vec3(.98,1.,1.), vec3(.78,.86,1.), uTheme);
        col += edgeTint * fres * .22 * edge;
        vec2 lightDir = normalize(vec2(-.8,-1.0));
        float glare = pow(max(0.0, dot(n, -lightDir)), 16.0) * edge;
        col += mix(vec3(.9,.95,1.0), vec3(.75,.86,1.0), uTheme) * glare * .25;
        float topGloss = smoothstep(-12.0, -1.0, d) * smoothstep(.95, .25, vUv.y);
        col += vec3(.22,.24,.28) * 0.0 + vec3(1.0) * topGloss * .045;
        float alpha = edge * .58;
        vec3 finalCol = mix(scene.rgb, col, alpha);
        outColor = vec4(finalCol, 1.0);
      }`;
    }
    program(vsSrc, fsSrc){
      const gl = this.gl;
      const compile = (type, src) => {
        const s = gl.createShader(type);
        gl.shaderSource(s, src);
        gl.compileShader(s);
        if(!gl.getShaderParameter(s, gl.COMPILE_STATUS)){
          throw new Error(gl.getShaderInfoLog(s) || "Shader compile error");
        }
        return s;
      };
      const vs = compile(gl.VERTEX_SHADER, vsSrc);
      const fs = compile(gl.FRAGMENT_SHADER, fsSrc);
      const p = gl.createProgram();
      gl.attachShader(p,vs);
      gl.attachShader(p,fs);
      gl.bindAttribLocation(p,0,"aPosition");
      gl.linkProgram(p);
      if(!gl.getProgramParameter(p, gl.LINK_STATUS)){
        throw new Error(gl.getProgramInfoLog(p) || "Program link error");
      }
      return p;
    }
    syncBoxes(){
      const selectors = ["#sidebar",".bubble",".lg"];
      const seen = new Set();
      const nodes = [];
      selectors.forEach(sel => {
        $$(sel).forEach(el => {
          if(seen.has(el)) return;
          const cs = getComputedStyle(el);
          if(cs.display === "none" || cs.visibility === "hidden") return;
          if(el.id === "ctx-menu" && !el.classList.contains("open")) return;
          if(el.id === "action-sheet" && !el.classList.contains("open")) return;
          const rect = el.getBoundingClientRect();
          if(rect.width < 18 || rect.height < 18) return;
          if(rect.bottom < 0 || rect.right < 0 || rect.top > innerHeight || rect.left > innerWidth) return;
          seen.add(el);
          nodes.push({el,rect});
        });
      });

      let key = "";
      const count = Math.min(nodes.length, this.maxBoxes);
      for(let i=0;i<count;i++){
        const {el,rect} = nodes[i];
        const cs = getComputedStyle(el);
        const rad = parseFloat(cs.borderTopLeftRadius) || 18;
        const x = rect.left * this.dpr;
        const y = (innerHeight - rect.bottom) * this.dpr;
        const w = rect.width * this.dpr;
        const h = rect.height * this.dpr;
        this.boxData[i*4+0] = x;
        this.boxData[i*4+1] = y;
        this.boxData[i*4+2] = w;
        this.boxData[i*4+3] = h;
        this.radiusData[i] = rad * this.dpr;
        key += `${Math.round(x)},${Math.round(y)},${Math.round(w)},${Math.round(h)},${Math.round(rad*10)};`;
      }
      this.boxCount = count;
      if(key !== this.lastRectsKey){
        this.lastRectsKey = key;
      }
      this.needsSync = false;
    }
    drawTo(target, prog, uniforms){
      const gl = this.gl;
      gl.bindFramebuffer(gl.FRAMEBUFFER, target);
      gl.viewport(0,0,this.canvas.width,this.canvas.height);
      gl.useProgram(prog);
      gl.bindBuffer(gl.ARRAY_BUFFER, this.quad);
      gl.enableVertexAttribArray(0);
      gl.vertexAttribPointer(0,2,gl.FLOAT,false,0,0);
      uniforms?.();
      gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
    }
    frame = () => {
      if(!this.ready) return;
      const gl = this.gl;
      const t = (performance.now() - this.timeStart) * .001;
      if(this.needsSync || t % .2 < .016) this.syncBoxes();

      this.drawTo(this.scene.fbo, this.bgProg, () => {
        gl.uniform1f(this.loc.bg.time, t);
        gl.uniform2f(this.loc.bg.res, this.canvas.width, this.canvas.height);
        gl.uniform1f(this.loc.bg.theme, html.getAttribute("data-theme") === "dark" ? 1 : 0);
      });

      this.drawTo(this.blurA.fbo, this.blurProg, () => {
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, this.scene.tex);
        gl.uniform1i(this.loc.blur.src, 0);
        gl.uniform2f(this.loc.blur.dir, 1, 0);
        gl.uniform2f(this.loc.blur.res, this.canvas.width, this.canvas.height);
        gl.uniform1fv(this.loc.blur.weights, this.weights);
        gl.uniform1i(this.loc.blur.radius, Math.min(12, this.weights.length - 1));
      });

      this.drawTo(this.blurB.fbo, this.blurProg, () => {
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, this.blurA.tex);
        gl.uniform1i(this.loc.blur.src, 0);
        gl.uniform2f(this.loc.blur.dir, 0, 1);
        gl.uniform2f(this.loc.blur.res, this.canvas.width, this.canvas.height);
        gl.uniform1fv(this.loc.blur.weights, this.weights);
        gl.uniform1i(this.loc.blur.radius, Math.min(12, this.weights.length - 1));
      });

      this.drawTo(null, this.mainProg, () => {
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, this.scene.tex);
        gl.uniform1i(this.loc.main.scene, 0);
        gl.activeTexture(gl.TEXTURE1);
        gl.bindTexture(gl.TEXTURE_2D, this.blurB.tex);
        gl.uniform1i(this.loc.main.blur, 1);
        gl.uniform2f(this.loc.main.res, this.canvas.width, this.canvas.height);
        gl.uniform1f(this.loc.main.time, t);
        gl.uniform1i(this.loc.main.boxCount, this.boxCount);
        gl.uniform4fv(this.loc.main.boxes, this.boxData);
        gl.uniform1fv(this.loc.main.radii, this.radiusData);
        gl.uniform1f(this.loc.main.theme, html.getAttribute("data-theme") === "dark" ? 1 : 0);
      });

      requestAnimationFrame(this.frame);
    }
  }

  const renderer = new MultiPassRenderer(canvas);

  loadChats();
  renderHistory();
  renderConversation();
  checkResumableJobs();

  setInterval(() => {
    const chat = getCurrentChat();
    if(chat?.activeJobId && !state.activeAbort) checkResumableJobs();
  }, 15000);
})();
</script>
